function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };

  const O='#2a0a0a', Red='#8a2020', RedLt='#c43c3c', Noise='#4a1010';
  px(0,0,32,32,O);
  for (let i=0;i<40;i++) {
    const x=(i*7+3)%30+1, y=(i*11+5)%30+1;
    px(x,y,2,2, i%3?Red:Noise);
  }
  px(10,10,12,12,RedLt); px(12,12,8,8,O);
  px(14,14,4,4,Red);

}
